'use strict';
const edit={zoom:1,selected:-1,draft:null,drag:null,visible:false,lastView:-1,history:[[],[]],brushStroke:null};
const NS='http://www.w3.org/2000/svg';
const zoneNames=['Защищённая деталь',...zones];
function validGeometry(v,width,height){return Array.isArray(v)&&v.length<=3000&&v.every(s=>Number.isInteger(s.zone)&&s.zone>=0&&s.zone<=4&&typeof s.name==='string'&&s.name.length<200&&Array.isArray(s.points)&&s.points.length>=3&&s.points.length<=3000&&s.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&p[0]>=-5&&p[1]>=-5&&p[0]<=width+5&&p[1]<=height+5));}
function validStrokes(v,width,height){return Array.isArray(v)&&v.length<=300&&v.every(s=>Number.isInteger(s.zone)&&s.zone>=0&&s.zone<=4&&Number.isFinite(s.radius)&&s.radius>0&&s.radius<=2048&&Array.isArray(s.points)&&s.points.length<=50000&&s.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&p[0]>=0&&p[1]>=0&&p[0]<width&&p[1]<height));}
function saveGeometry(){if(!state.ready)return;try{localStorage.setItem('facade-geometry-v2',JSON.stringify({version:2,views:data.map(d=>({width:d.width,height:d.height,shapes:d.shapes,strokes:d.strokes}))}));$('mask-save-status').textContent='Разметка сохранена в этом браузере';}catch{$('mask-save-status').textContent='Не удалось сохранить — скачайте разметку';}}
function snapshot(){const d=data[state.view];const h=edit.history[state.view];h.push({shapes:clone(d.shapes),strokes:clone(d.strokes)});if(h.length>20)h.shift();}
function rasterizeShapes(shapes,width,height){const c=document.createElement('canvas');c.width=width;c.height=height;const x=c.getContext('2d',{willReadFrequently:true});for(const s of shapes){x.beginPath();s.points.forEach((p,i)=>i?x.lineTo(...p):x.moveTo(...p));x.closePath();x.globalCompositeOperation=s.zone===0?'destination-out':'source-over';x.fillStyle=`rgb(${s.zone*50},0,0)`;x.fill();}const raw=x.getImageData(0,0,width,height).data,m=new Uint8Array(width*height);for(let p=0;p<m.length;p++)if(raw[p*4+3]>127)m[p]=Math.min(4,Math.max(0,Math.round(raw[p*4]/50)));return m;}
function strokeToMask(mask,stroke,width,height){const {radius,zone}=stroke;for(const p of stroke.points)for(let y=Math.max(0,Math.floor(p[1]-radius));y<=Math.min(height-1,Math.ceil(p[1]+radius));y++)for(let x=Math.max(0,Math.floor(p[0]-radius));x<=Math.min(width-1,Math.ceil(p[0]+radius));x++){if((x-p[0])**2+(y-p[1])**2<=radius**2)mask[y*width+x]=zone;}}
function rebuildMask(){const d=data[state.view];d.mask=rasterizeShapes(d.shapes,d.width,d.height);for(let p=0;p<d.mask.length;p++)if(d.occlusion[p])d.mask[p]=0;for(const stroke of d.strokes)strokeToMask(d.mask,stroke,d.width,d.height);schedule();}
function setupEditor(){try{const stored=JSON.parse(localStorage.getItem('facade-geometry-v2')||'null');if(stored?.version===2&&stored.views?.length===2){stored.views.forEach((v,i)=>{const d=data[i];if(v.width===d.width&&v.height===d.height&&validGeometry(v.shapes,d.width,d.height)&&validStrokes(v.strokes||[],d.width,d.height)){d.shapes=v.shapes;d.strokes=v.strokes||[];const previous=state.view;state.view=i;rebuildMask();state.view=previous;}});}}catch{}refreshEditor();}
function svgElement(tag,attrs){const e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;}
function currentContours(){if(!state.ready)return [];const f=$('contour-filter').value;return data[state.view].shapes.map((s,i)=>({s,i})).filter(({s})=>f==='all'||s.zone===Number(f));}
function refreshEditor(){if(!state.ready)return;if(edit.lastView!==state.view){edit.selected=-1;edit.draft=null;edit.lastView=state.view;}const select=$('contour-select'),items=currentContours();select.replaceChildren();const empty=document.createElement('option');empty.value='-1';empty.textContent='Выберите контур на фото или в списке';select.append(empty);items.forEach(({s,i})=>{const opt=document.createElement('option');opt.value=i;opt.textContent=(i+1)+' · '+s.name;select.append(opt);});select.value=edit.selected;drawContours();}
function drawContours(){if(!state.ready)return;const svg=$('contour-overlay'),d=data[state.view];svg.setAttribute('viewBox',`0 0 ${d.width} ${d.height}`);svg.replaceChildren();svg.classList.toggle('active',edit.visible||!!edit.draft);if(!edit.visible&&!edit.draft)return;
 const scale=d.width/$('canvas').getBoundingClientRect().width;
 for(const {s,i}of currentContours()){const active=i===edit.selected;const el=svgElement('polygon',{points:s.points.map(p=>p.join(',')).join(' '),fill:active?'#f7bf4930':'transparent',stroke:active?'#f7bf49':s.zone===0?'#6ad5ea':'#fff','stroke-width':active?2:1,'vector-effect':'non-scaling-stroke','data-contour':i});svg.append(el);}
 const selected=d.shapes[edit.selected];if(selected){$('contour-info').textContent=zoneNames[selected.zone]+' · '+selected.points.length+' вершин';selected.points.forEach((p,i)=>svg.append(svgElement('circle',{cx:p[0],cy:p[1],r:4*scale,fill:'#f7bf49',stroke:'#282e2a','stroke-width':scale,'data-vertex':i})));}else $('contour-info').textContent=itemsCountText();
 if(edit.draft){svg.append(svgElement('polyline',{points:edit.draft.points.map(p=>p.join(',')).join(' '),fill:'none',stroke:'#ffb848','stroke-width':2,'vector-effect':'non-scaling-stroke'}));for(const p of edit.draft.points)svg.append(svgElement('circle',{cx:p[0],cy:p[1],r:3*scale,fill:'#ffb848'}));}
}
function itemsCountText(){return currentContours().length+' контуров · вершины можно перетаскивать';}
function setZoom(z){edit.zoom=Math.min(8,Math.max(1,z));$('photo-stage').style.width=edit.zoom*100+'%';$('zoom-value').textContent=Math.round(edit.zoom*100)+'%';drawContours();}
$('zoom-in').onclick=()=>setZoom(edit.zoom*1.5);$('zoom-out').onclick=()=>setZoom(edit.zoom/1.5);$('zoom-reset').onclick=()=>{setZoom(1);$('photo').scrollTo(0,0);};
$('show-contours').onchange=e=>{edit.visible=e.target.checked;if(edit.visible){$('brush').value='off';$('brush').onchange();}drawContours();};
$('contour-filter').onchange=()=>{edit.selected=-1;refreshEditor();};
$('contour-select').onchange=e=>{edit.selected=Number(e.target.value);edit.visible=true;$('show-contours').checked=true;$('brush').value='off';$('brush').onchange();drawContours();};
function polygonArea(points){let area=0;for(let i=0,j=points.length-1;i<points.length;j=i++)area+=points[j][0]*points[i][1]-points[i][0]*points[j][1];return Math.abs(area/2);}
function pointInPolygon(p,points){let inside=false;for(let i=0,j=points.length-1;i<points.length;j=i++){const a=points[i],b=points[j];if(((a[1]>p.y)!==(b[1]>p.y))&&(p.x<(b[0]-a[0])*(p.y-a[1])/(b[1]-a[1])+a[0]))inside=!inside;}return inside;}
function snapVertex(point,exclude=-1){const d=data[state.view],scale=d.width/$('canvas').getBoundingClientRect().width,r=4*scale;let best=r*r,result=[point.x,point.y];for(const {s,i}of currentContours())for(let k=0;k<s.points.length;k++){if(i===edit.selected&&k===exclude)continue;const p=s.points[k],dist=(p[0]-point.x)**2+(p[1]-point.y)**2;if(dist<best){best=dist;result=p.slice();}}return result.map(v=>Math.round(v*10)/10);}
const svg=$('contour-overlay');
svg.onpointerdown=e=>{if(!state.ready)return;e.preventDefault();const p=canvasPoint(e);if(edit.draft){edit.draft.points.push([Math.round(p.x*10)/10,Math.round(p.y*10)/10]);drawContours();return;}const v=e.target.getAttribute('data-vertex');if(v!==null&&edit.selected>=0){snapshot();edit.drag=Number(v);svg.setPointerCapture(e.pointerId);return;}const matches=currentContours().filter(({s})=>pointInPolygon(p,s.points)).sort((a,b)=>polygonArea(a.s.points)-polygonArea(b.s.points));if(matches.length){edit.selected=matches[0].i;$('contour-select').value=edit.selected;drawContours();}};
svg.onpointermove=e=>{if(edit.drag===null)return;const d=data[state.view],p=canvasPoint(e);p.x=Math.max(0,Math.min(d.width,p.x));p.y=Math.max(0,Math.min(d.height,p.y));d.shapes[edit.selected].points[edit.drag]=e.altKey?[Math.round(p.x*10)/10,Math.round(p.y*10)/10]:snapVertex(p,edit.drag);drawContours();};
function stopDrag(){if(edit.drag!==null){edit.drag=null;rebuildMask();saveGeometry();}}svg.onpointerup=stopDrag;svg.onpointercancel=stopDrag;
$('polygon-start').onclick=()=>{if(!state.ready)return;edit.draft={zone:Number($('polygon-zone').value),name:'Ручной контур',points:[]};edit.visible=true;$('show-contours').checked=true;$('brush').value='off';$('brush').onchange();drawContours();toast('Расставьте вершины на фото. Затем нажмите «Замкнуть».');};
$('polygon-finish').onclick=()=>{if(!edit.draft||edit.draft.points.length<3){toast('Для контура нужны минимум три точки');return;}if(polygonArea(edit.draft.points)<1){toast('Точки должны образовать площадь');return;}snapshot();data[state.view].shapes.push(edit.draft);edit.selected=data[state.view].shapes.length-1;edit.draft=null;rebuildMask();saveGeometry();refreshEditor();};
$('polygon-cancel').onclick=()=>{edit.draft=null;drawContours();};
$('contour-delete').onclick=()=>{if(edit.selected<0)return;snapshot();data[state.view].shapes.splice(edit.selected,1);edit.selected=-1;rebuildMask();saveGeometry();refreshEditor();};
$('geometry-undo').onclick=()=>{const prior=edit.history[state.view].pop();if(!prior)return toast('Нет правок для отмены');const d=data[state.view];d.shapes=prior.shapes;d.strokes=prior.strokes;edit.selected=-1;rebuildMask();saveGeometry();refreshEditor();};
// Brush strokes are saved as paths, so they survive reloads and contour changes.
$('canvas').onpointerdown=e=>{if(!state.ready||$('brush').value==='off')return;e.preventDefault();snapshot();const d=data[state.view],p=canvasPoint(e);p.x=Math.max(0,Math.min(d.width-1,p.x));p.y=Math.max(0,Math.min(d.height-1,p.y));edit.brushStroke={zone:Number($('brush').value),radius:Math.min(2048,Number($('brush-size').value)*d.width/$('canvas').getBoundingClientRect().width/2),points:[[p.x,p.y]]};$('canvas').setPointerCapture(e.pointerId);strokeToMask(d.mask,edit.brushStroke,d.width,d.height);schedule();};
$('canvas').onpointermove=e=>{if($('brush').value==='off')return;const r=$('photo-stage').getBoundingClientRect(),sz=Number($('brush-size').value);$('brush-cursor').style.cssText=`display:block;width:${sz}px;height:${sz}px;left:${e.clientX-r.left-sz/2}px;top:${e.clientY-r.top-sz/2}px`;if(!edit.brushStroke)return;const d=data[state.view],p=canvasPoint(e);p.x=Math.max(0,Math.min(d.width-1,p.x));p.y=Math.max(0,Math.min(d.height-1,p.y));const s=edit.brushStroke,last=s.points[s.points.length-1],steps=Math.max(1,Math.ceil(Math.hypot(p.x-last[0],p.y-last[1])/Math.max(1,s.radius/2))),points=[];for(let j=1;j<=steps;j++)points.push([last[0]+(p.x-last[0])*j/steps,last[1]+(p.y-last[1])*j/steps]);s.points.push(...points);strokeToMask(d.mask,{...s,points},d.width,d.height);schedule();};
function finishBrush(){if(!edit.brushStroke)return;data[state.view].strokes.push(edit.brushStroke);edit.brushStroke=null;saveGeometry();}
$('canvas').onpointerup=finishBrush;$('canvas').onpointercancel=finishBrush;
const oldBrushChange=$('brush').onchange;$('brush').onchange=()=>{if($('brush').value!=='off'){edit.visible=false;$('show-contours').checked=false;edit.draft=null;drawContours();}oldBrushChange();};
$('undo').onclick=()=>{const d=data[state.view];if(!d?.strokes.length)return toast('Нет мазков для отмены');snapshot();d.strokes.pop();rebuildMask();saveGeometry();};
$('mask-reset').onclick=()=>{if(!state.ready)return;snapshot();const d=data[state.view];d.shapes=clone(d.baseShapes);d.strokes=[];d.mask=d.baseMask.slice();edit.selected=-1;saveGeometry();refreshEditor();schedule();toast('Исходная геометрическая разметка восстановлена');};
$('mask-export').onclick=()=>{if(!state.ready)return;download(new Blob([JSON.stringify({version:2,views:data.map(d=>({width:d.width,height:d.height,shapes:d.shapes,strokes:d.strokes}))})],{type:'application/json'}),'facade-mask-geometry.json');};
$('mask-import').onchange=async e=>{const f=e.target.files[0];if(!f||!state.ready)return;try{if(f.size>12*1024*1024)throw Error('Файл разметки слишком большой');const v=JSON.parse(await f.text());if(v.version!==2||v.views?.length!==2||v.views.some((s,i)=>s.width!==data[i].width||s.height!==data[i].height||!validGeometry(s.shapes,s.width,s.height)||!validStrokes(s.strokes||[],s.width,s.height)))throw Error('Формат или размеры разметки не совпадают');const view=state.view;v.views.forEach((s,i)=>{state.view=i;snapshot();data[i].shapes=s.shapes;data[i].strokes=s.strokes||[];rebuildMask();});state.view=view;edit.selected=-1;saveGeometry();refreshEditor();schedule();toast('Разметка обоих ракурсов загружена');}catch(err){toast(err.message);}e.target.value='';};

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&edit.draft){edit.draft=null;drawContours();}});
